export type ParsedSettleNoteInstruction<
  TProgram extends string = typeof BUCKSPAY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    /** Pays the rent of the records; the fee payer in the usual case. */
    payer: TAccountMetas[0]
    lock: TAccountMetas[1]
    ledger: TAccountMetas[2]
    escrow: TAccountMetas[3]
    mint: TAccountMetas[4]
    /**
     * Any token account of the mint; the handler requires its owner to be the account the note
     * pays. The escrow is refused by the runtime's duplicate-account check as well.
     */
    destination: TAccountMetas[5]
    instructions: TAccountMetas[6]
    tokenProgram: TAccountMetas[7]
    systemProgram: TAccountMetas[8]
  }
  data: SettleNoteInstructionData
}

export function parseSettleNoteInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleNoteInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 9,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      lock: getNextAccount(),
      ledger: getNextAccount(),
      escrow: getNextAccount(),
      mint: getNextAccount(),
      destination: getNextAccount(),
      instructions: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSettleNoteInstructionDataDecoder().decode(instruction.data),
  }
}
